#pragma once#include "Windows.h"namespace AutoScroll {	enum Direction	{		None  =  0,  // -1: left/up, 1: right/down, 0: нет скролла		Left  = -1,		Right =  1,		Up    = -2,		Down  =  2	};}namespace WM_MSG_RESULT{	class WM_NCLBUTTONDOWN_Result{	public:		static const LRESULT PROCESSED = 0; static const LRESULT NOT_PROCESSED = 1;    };        class WM_NCLBUTTONUP_Result{	public:		static const LRESULT PROCESSED = 0; static const LRESULT NOT_PROCESSED = 1;    };}namespace Scroll{	BOOL GetWindowRect(		__in HWND hWnd,		__out LPRECT lpRect);}class CScrollManager{public:	CScrollManager(HWND hWnd) 		:m_hWnd(hWnd)		, m_HScrollBar(false)		, m_VScrollBar(false)		, m_VscrollPosition(0)		, m_HscrollPosition(0)		, m_scrollDirection(AutoScroll::None)		, m_scrollTimerId(1002) //<-- ручной рэндом: оста¸тся только надеяться, что такого идентификатора таймера в коде больше нет	{}	~CScrollManager(void){}	//Это вызывается до обработки оконных сообщений, до отрисовки.    void LimitWindowSizeAndAddScrollBars (SIZE& szWinMax, SIZE& sz);  	//WM_NCLBUTTONDOWN	LRESULT HandleScrollBarMouseDown(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam);	//WM_NCLBUTTONUP	LRESULT HandleScrollBarMouseUp(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam);	//OnTimer	LRESULT HandleScrollBarAutoScroll(HWND hWnd, UINT timerId);	BOOL IsScrolling()		{	return m_scrollDirection !=  AutoScroll::None;}	BOOL IsExistsScrollBar(){	return m_VScrollBar||m_HScrollBar;}	int GetVscrollPosition(){	return m_VscrollPosition;}	int GetHscrollPosition(){	return m_HscrollPosition;}	bool ExistsVScrollBar(){	return m_VScrollBar;	}	bool ExistsHScrollBar(){	return m_HScrollBar;	}	//WM_SIZING	BOOL ProcessSizing(UINT fwSide, LPRECT pDragRectangle, SIZE* szWndContent);	//Это WM_SIZE	void HandleWindowResized(SIZE* szWndContent, RECT* clinetRectangle);	//WM_MOUSEWHEEL	LRESULT ProcessWM_MOUSEWHEEL_HScroll(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam);  	LRESULT ProcessWM_MOUSEWHEEL_VScroll(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam);  	//WM_VSCROLL	LRESULT HandleVScroll(HWND hwnd,  UINT uMsg, WPARAM wParam, LPARAM lParam);	//WM_HSCROLL	LRESULT HandleHScroll(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam);protected:	HWND m_hWnd;	bool m_HScrollBar;	bool m_VScrollBar;	int m_VscrollPosition;	int m_HscrollPosition;	bool m_limitedHeight;	AutoScroll::Direction m_scrollDirection;	UINT m_scrollTimerId;	void SetScrollInfo(SIZE* szWndContent, RECT* clinetRectangle);	void RemoveHScroll(SIZE* pNewWndSize);	void AddHScroll(SIZE& sz);	void RemoveVScroll(SIZE* pNewWndSize);	void AddVScroll(SIZE& sz);  	LRESULT HandleVerticalScrollBarClick(POINT pt);	LRESULT HandleHorizontalScrollBarClick(POINT pt);	int CalculateVscrollPosition(bool autoScroll);	int CalculateHscrollPosition(bool autoScroll);	RECT GetVerticalScrollBarRect(bool includeArrows = true);	RECT GetVerticalThumbRect();	RECT GetHorizontalScrollBarRect(bool includeArrows = true);	RECT GetHorizontalThumbRect();};